function searchStores({ city, keyword } = {}) {
  let list = STORE_DB;
  if (city) list = list.filter(s => s.city === city);
  if (keyword && keyword.trim()) {
    const kw = keyword.trim();
    list = list.filter(s => s.addr.includes(kw) || s.name.includes(kw));
  }
  return list.slice(0, 50);
}

function searchStoresByName(keyword) {
  if (!keyword || !keyword.trim()) return [];
  const kw = keyword.trim();
  return STORE_DB.filter(s => s.name.includes(kw)).slice(0, 50);
}

function searchStoresByCode(codeQuery) {
  if (!codeQuery || !codeQuery.trim()) return [];
  const kw = codeQuery.trim();
  return STORE_DB.filter(s => s.code.includes(kw)).slice(0, 50);
}

function findStoreByCode(code) {
  if (!code) return null;
  return STORE_DB.find(s => s.code === code) || null;
}
